INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note)
VALUES
  ('warlord-light-machine-cyborg', 1, 'Concealed Vibro-Blades (2)', '2D4 M.D. each', 1, 'Melee', 'Melee weapons; each strike counts as one attack', 'Unlimited; draws on the ''Borg''s power supply', NULL, 'Primary purpose: anti-personnel. A retractable Vibro-Short Sword in each forearm, extended at will and locked in place. May be silver plated.'),
  ('warlord-light-machine-cyborg', 2, 'Ion Palm/Wrist Blaster (1 or 2)', '3D6 M.D. per blast; 6D6 M.D. for both fired together', 1, '500 feet (152 m)', 'Each blast counts as one melee attack. Both blasters fired together at one target do double damage (6D6 M.D.) and count as one melee attack, but only while standing still and against a target at least two times human-size.', 'Effectively unlimited; runs on internal power supply', NULL, 'Primary purpose: assault. Built into one or both hands/wrists; retracts when not in use. With only one unit, the other hand typically carries a chemical spray, garrote wrist wire, or wrist needle and drug dispenser. Shooting while running counts as shooting wild: -6 to strike and all other combat bonuses halved.'),
  ('sovietski-light-machine-cyborg', 1, 'Concealed Vibro-Blades (2)', '2D4 M.D. each', 1, 'Melee', 'Melee weapons; each strike counts as one attack', 'Unlimited; draws on the ''Borg''s power supply', NULL, 'Primary purpose: anti-personnel. A retractable Vibro-Short Sword in each forearm, extended at will and locked in place.'),
  ('sovietski-light-machine-cyborg', 2, 'Ion Palm/Wrist Blaster (1 or 2)', '3D6 M.D. per blast; 6D6 M.D. for both fired together', 1, '500 feet (152 m)', 'Each blast counts as one melee attack. Both blasters fired together at one target do double damage (6D6 M.D.) and count as one melee attack, but only while standing still and against a target at least two times human-size.', 'Effectively unlimited; runs on internal power supply', NULL, 'Primary purpose: assault. Built into one or both hands/wrists; retracts when not in use. With only one unit, the other hand typically carries a chemical spray, garrote wrist wire, or wrist needle and drug dispenser. Shooting while running counts as shooting wild: -6 to strike and all other combat bonuses halved.'),
  ('sovietski-heavy-machine-cyborg', 1, 'Concealed Vibro-Blades (2)', '2D4 M.D. each', 1, 'Melee', 'Melee weapons; each strike counts as one attack', 'Unlimited; draws on the ''Borg''s power supply', NULL, 'Primary purpose: anti-personnel. A retractable Vibro-Blade housed in the small shielding over each wrist and hand, extended at will and locked in place. The M.D.C. table calls these Retractable Vibro-Knives.'),
  ('sovietski-heavy-machine-cyborg', 2, 'Ion Palm/Wrist Blaster (1 or 2)', '3D6 M.D. per blast; 6D6 M.D. for both fired together', 1, '500 feet (152 m)', 'Each blast counts as one melee attack. Both blasters fired together at one target do double damage (6D6 M.D.) and count as one melee attack, but only while standing still and against a target at least two times human-size.', 'Effectively unlimited; runs on internal power supply', NULL, 'Primary purpose: assault. Built into one or both hands/wrists; retracts when not in use. With only one unit, the other hand typically carries a chemical spray, garrote wrist wire, or wrist needle and drug dispenser. Shooting while running counts as shooting wild: -6 to strike and all other combat bonuses halved.'),
  ('thunderhammer-cyborg-shocktrooper', 1, 'Mini-Missile Launch System', 'Varies with missile type; standard issue armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'About a mile (1.6 km)', 'One at a time or volleys of two or four', '32 total', NULL, 'Primary purpose: anti-aircraft and anti-flying monsters. Built into the back. Any mini-missile can be used; fragmentation may be used against ground troops.'),
  ('thunderhammer-cyborg-shocktrooper', 2, 'High-Powered Laser (right arm)', '3D6 M.D. per single blast', 1, '3,000 ft (914 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose: anti-personnel and defense. Forearm weapon; point and shoot. The M.D.C. table calls it the Heavy Laser.'),
  ('thunderhammer-cyborg-shocktrooper', 3, 'W-42 Concealed Palm Laser', 'Four settings: 2D4x10 S.D.C., 1D4 M.D., 1D6 M.D., or 2D6 M.D. per single blast', 1, '400 feet (122 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose: tactical weapon and tool/self-defense. A larger, heavier W-42 with better range, in the base of the left palm and wrist; also a cutting tool.'),
  ('thunderhammer-cyborg-shocktrooper', 4, 'Plasma Ejector', '6D6 M.D. per single blast', 1, '1,000 ft (305 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose: anti-personnel and defense. Left forearm; its energy needs leave no room for a second forearm weapon or extra appendage there.'),
  ('thunderhammer-cyborg-shocktrooper', 5, 'Vibro-Blade Knuckle Claws', '3D4 M.D. per raking claw strike, or +3D4 M.D. to punch damage in a punching strike', 1, 'Hand to hand; the reach of the arm, about 8 feet (2.4 m)', NULL, NULL, NULL, 'Optional. Only with the three-fingered hand; extendable knuckle blades on one or both hands; silver plated.'),
  ('thunderhammer-cyborg-shocktrooper', 6, 'Vibro-Sickle', '3D6+2 M.D.', 1, 'Hand to hand; about 11 feet (3.3 m; 3 feet/0.9 m longer than the arm)', NULL, NULL, NULL, 'Large curved hand-held Vibro-Blade for slashing, chopping and parrying; giant-sized. Weight 70 pounds (32 kg). 80 M.D.C.'),
  ('thunderhammer-cyborg-shocktrooper', 7, 'Large Energy Hammer', '2D6 M.D. per physical strike or 2D6 M.D. per single blast; 5D6 S.D.C./H.P. when the hammer is without energy', 1, '500 ft (152 m)', 'Each blast counts as one melee attack', '30 energized strikes or blasts per E-Clip (concealed in the back of the hammer''s head); effectively unlimited if cabled to the cyborg', NULL, 'Primary purpose: hand to hand combat. Hand-held; both a blunt M.D. weapon and an energy blaster. Weight 80 pounds (36 kg). 90 M.D.C.'),
  ('thunderhammer-cyborg-shocktrooper', 8, 'Robot P.S. and Punch Damage', 'Restrained punch 1D4 M.D.; full strength punch or kick 2D6 M.D.; power punch or leap kick 4D6 M.D.', 1, 'Melee', 'Power punch or leap kick counts as two attacks', NULL, NULL, 'Hand to hand damage from Robotic P.S. 38.'),
  ('thunderstrike-cyborg-shocktrooper', 1, 'Rail Guns (2)', '1D4x10 M.D. per 16 round burst', 1, '4,000 feet (1200 m)', 'Only fires 16 round bursts; each counts as one melee attack', 'A pair of 3200 round drums (200 bursts per arm) are standard issue; a 160 round clip (10 bursts) and 400 round belt (25 bursts) are also available', NULL, 'Primary purpose: anti-armor and monsters. Secondary purpose: anti-aircraft and anti-personnel. One in each forearm; full-size rail gun range and damage rather than the mini-versions on most ''Borgs.'),
  ('thunderstrike-cyborg-shocktrooper', 2, 'W-42 Concealed Palm Laser (2)', 'Four settings: 2D4x10 S.D.C., 1D4 M.D., 1D6 M.D., and 2D6 M.D. per single blast', 1, '400 feet (122 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose: tactical weapon and tool/self-defense. A small laser in the base of each palm and wrist; also a cutting tool.'),
  ('thunderstrike-cyborg-shocktrooper', 3, 'Vibro-Blade Knuckle Claws', '4D4 M.D. per raking claw strike, or +4D4 M.D. to punch damage in a knuckle strike/punch', 1, 'Hand to hand; the reach of the arm, about 8 feet (2.4 m)', NULL, NULL, NULL, 'Extendable knuckle blades built into each hand; silver plated.'),
  ('thunderstrike-cyborg-shocktrooper', 4, 'Vibro-Sickle or Energy Hammer', 'Vibro-Sickle 3D6+2 M.D.; Energy Hammer 2D6 M.D. per physical strike or per single blast (5D6 S.D.C./H.P. without energy); giant Vibro-Sword 4D6 M.D.', 1, 'Vibro-Sickle: hand to hand; Energy Hammer blast 500 ft (152 m)', 'Energy Hammer: each blast counts as one melee attack', 'Energy Hammer: 30 energized strikes or blasts per E-Clip; effectively unlimited if cabled to the cyborg', NULL, 'One or the other is typically chosen as a sidearm (sometimes both, or the Hammer and a giant Vibro-Sword); the Hammer is a bit more popular. This entry prints only the Vibro-Sword''s damage and says to see the Thunderhammer Cyborg; the Sickle and Hammer figures here are the Thunderhammer''s (p.219).'),
  ('thunderstrike-cyborg-shocktrooper', 5, 'Robot P.S. and Punch Damage', 'Restrained punch 1D6 M.D.; full strength punch or kick 3D6 M.D.; power punch or leap kick 1D6x10 M.D.; head butt or stomp 1D6 M.D.', 1, 'Melee', 'Power punch or leap kick counts as two attacks', NULL, NULL, 'Hand to hand damage from Robotic P.S. 42.'),
  ('thunderstorm-artillery-cyborg', 1, 'Artillery Unit: Cannons', '2D4x10 M.D. per single round; 4D4x10 M.D. per double, simultaneous blast (two rounds)', 1, '8,300 feet (2530 m); about a mile and a half', 'Each single or double blast counts as one melee attack', '20 cannon shells total, for 10 double blasts or 20 single ones. A three-man team with two wearing MM-61 Explorer Exoframes (p.176) or two being Light or Heavy Machines can reload four shells per melee round', NULL, 'Primary purpose: tactical bombardment of the enemy. Secondary purpose: anti-armored vehicles and infantry support. A self-loading, double-barrelled Howitzer; the cyborg must brace on all fours to fire.'),
  ('thunderstorm-artillery-cyborg', 2, 'Artillery Unit: Mini-Missiles', 'Varies with missile type', 1, 'One mile (1.6 km)', NULL, NULL, NULL, 'Part of weapon system 1. Five mini-missile launch tubes on each side of the cannon housing (p.221). No rate of fire or payload is printed for the missiles.'),
  ('thunderstorm-artillery-cyborg', 3, 'Rail Guns (2)', '1D4x10 M.D. per 16 round burst', 1, '4,000 feet (1200 m)', 'Only fires 16 round bursts; each counts as one melee attack', 'A 3200 round drum per arm (200 bursts per arm) is standard issue; a 160 round clip (10 bursts) and 400 round belt (25 bursts) are also available', NULL, 'Primary purpose: anti-armor and monsters. Secondary purpose: anti-aircraft and anti-personnel. One in each forearm; full-size rail gun range and damage.'),
  ('thunderstorm-artillery-cyborg', 4, 'Concealed Laser Rods (2)', '3D6 M.D. per single blast', 1, '2000 feet (610 m)', 'A single or double cluster blast counts as one melee attack (as printed)', 'Effectively unlimited', NULL, 'Primary purpose: anti-personnel and defense. One concealed in each arm; remove, point and fire. Used for precision shooting. No damage is printed for a double blast.'),
  ('thunderstorm-artillery-cyborg', 5, 'Head Laser Clusters (2)', '1D6x10 M.D. per single cluster bombardment or 2D6x10 M.D. per simultaneous attack from both clusters', 1, '2000 feet (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose: anti-personnel and defense. Canisters on both sides of the face open to reveal three-barrelled lasers; fired one cluster at a time or together.'),
  ('thunderstorm-artillery-cyborg', 6, 'Vibro-Blade Knuckle Claws', '4D6 M.D. per raking claw strike, or +4D6 M.D. to punch damage in a knuckle strike/punch', 1, 'Hand to hand; the reach of the arm, about 9 feet (2.7 m) with blades extended', NULL, NULL, NULL, 'Extendable knuckle blades built into each hand; silver plated.'),
  ('thunderstorm-artillery-cyborg', 7, 'Robot P.S. and Punch Damage', 'Restrained punch 1D6 M.D.; full strength punch or kick 3D6 M.D.; power punch or leap kick 1D6x10 M.D.; head butt or stomp 2D6 M.D.', 1, 'Melee', 'Power punch or leap kick counts as two attacks', NULL, NULL, 'Hand to hand damage from Robotic P.S. 45.'),
  ('tempest-cyborg-shocktrooper', 1, 'Breathe Fire/Flame Thrower', '2D6 M.D. per blast', 1, '100 feet (30.5 m)', 'Each blast counts as one melee attack', '12 blasts before the fuel canister needs replacing', NULL, 'Primary purpose anti-personnel and defense. Fired from the mouth of the dragon head.'),
  ('tempest-cyborg-shocktrooper', 2, 'Laser Beam Eyes', '1D6 M.D. per single blast, 2D6 M.D. per simultaneous dual blast at the same target', 1, '1,600 ft (488 m)', 'Each blast counts as one melee attack; a dual blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-personnel and defense. Two tiny lasers hidden just under the glowing red eyes; line-of-sight aiming, the head must move to aim.'),
  ('tempest-cyborg-shocktrooper', 3, 'Concealed Forearm Laser', 'Adjustable: 1D6 or 2D6 M.D. per blast', 1, '1,600 ft (488 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose cutting tool and precision shooting/sniping. Pops out of a hidden forearm compartment, typically the left arm.'),
  ('tempest-cyborg-shocktrooper', 4, 'Forearm Plasma Gun', '6D6 M.D. per blast', 1, '1,200 feet (366 m)', 'Each blast counts as one melee attack', 'Effectively unlimited; draws on the cyborg''s power supply via a connecting cable', NULL, 'Primary purpose anti-personnel/anti-vehicle. Typically worn on the right forearm. May be replaced by the rail gun.'),
  ('tempest-cyborg-shocktrooper', 5, 'Forearm Rail Gun', '1D4x10 M.D. per burst', 1, '4000 feet (1200 m)', NULL, '100 bursts', NULL, 'Optional alternative to the Forearm Plasma Gun. Requires an ammo-drum hooked to the back behind the head, between the wings. No rate of fire is printed. Shares the 60 M.D.C. forearm gun location.'),
  ('tempest-cyborg-shocktrooper', 6, 'Mini-Missile Shoulder Launchers (2)', 'Varies with missile type; standard issue is armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'About a mile (1.6 km)', 'One at a time or volleys of two or four', '8 total, four per shoulder', NULL, 'Primary purpose anti-aircraft and flying monsters. Any mini-missile can be used; fragmentation may be used against ground troops. Four-shot launchers mounted on the shoulders under armored plates.'),
  ('tempest-cyborg-shocktrooper', 7, 'Vibro-Blade Finger Claws', '4D4 M.D. per claw strike', 1, 'Hand to hand; reach of the arm, about 6 feet (1.8 m)', NULL, NULL, NULL, 'Vibro-Blades on the fingers of each hand.'),
  ('tempest-cyborg-shocktrooper', 8, 'Vibro-Blade Feet', '+3D6 M.D. to kick damage (in addition to P.S. damage), or 1D6 M.D. from a glancing blow/cut', 1, 'Hand to hand; reach of the leg, about 7 feet (2.1 m)', NULL, NULL, NULL, 'Foot long Vibro-Blades on the feet; a glancing blow is one of the outer toe-blades hitting. Used to rake and stab on a flying pass.'),
  ('tempest-cyborg-shocktrooper', 9, 'Spiked Prehensile Tail', '4D6 M.D. from the spiked tail; 3D6 M.D. from the Electro-Spike/Ball at the tip, by touch or short-range blast', 1, 'Hand to hand; reach of the tail, about 10 feet (3 m); short-range blast up to 20 feet (6 m)', NULL, NULL, NULL, 'The 10 foot (3 m) tail slashes with its spikes, strikes with the electrically charged ball or spike at its tip, or grabs, holds and carries. It provides the +1 melee attack listed under Bonuses.'),
  ('tempest-cyborg-shocktrooper', 10, 'Robot P.S. and Punch Damage', 'Claw Strike 4D4 M.D.; Head Butt with Spikes 3D6 M.D.; Tail Strike 4D6 M.D.; Restrained Punch 1D4 M.D.; Full Strength Punch 2D6 M.D.; Power Punch 4D6 M.D.; Kick 2D6 M.D. +3D6 Vibro-Blade damage', 1, 'Hand to hand', NULL, NULL, NULL, 'Robotic P.S. 38. Unlike the other bodies, no "counts as two attacks" is printed on the Power Punch line.'),
  ('butcher-cyborg-shocktrooper', 1, 'Mini-Missile Forearm Launch Tubes (3)', 'Varies with missile type; standard issue is armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'About a mile (1.6 km)', 'One at a time or volleys of three', '9 total, three per launcher', NULL, 'Primary purpose anti-aircraft and flying monsters. Any mini-missile can be used; fragmentation may be used against ground troops. Right forearm. The text says four three-shot launchers are mounted there but only three hold missiles; the fourth is the laser (weapon 2).'),
  ('butcher-cyborg-shocktrooper', 2, 'High-Powered Laser', '3D6 M.D. per single blast', 1, '3,000 ft (914 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-personnel and defense. Disguised as one of the mini-missile launchers on the right forearm.'),
  ('butcher-cyborg-shocktrooper', 3, 'Vibro-Blade Knuckle Claws', '4D4 M.D. per raking claw strike, or add +4D4 M.D. to punch damage in a punching strike', 1, 'Hand to hand; reach of the arm, about 8 feet (2.4 m)', NULL, NULL, NULL, 'On the knuckles of the right hand; silver plated. The punch table (weapon 6) prints the Vibro-Knuckle Punch as 4D6+2 M.D.'),
  ('butcher-cyborg-shocktrooper', 4, 'W-42 Concealed Palm Laser', 'Four settings: 2D4x10 S.D.C., 1D4 M.D., 1D6 M.D., or 2D6 M.D. per single blast', 1, '400 feet (122 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose tactical weapon and tool/self-defense. A larger, heavier W-42 built into the base of the left palm and wrist; also a cutting tool.'),
  ('butcher-cyborg-shocktrooper', 5, 'Vibro-Swords', '3D6 M.D. for one blade, or 6D6 M.D. from two', 1, 'Hand to hand; about 10 feet (3 m) when extended (3 feet/0.9 m longer than the arm)', NULL, NULL, NULL, 'Two large, jagged, retractable blades built into the left arm; one or both can be extended. Good for parrying and striking.'),
  ('butcher-cyborg-shocktrooper', 6, 'Robot P.S. and Punch Damage', 'Raking Knuckle Claws 4D4 M.D.; Vibro-Knuckle Punch 4D6+2 M.D.; Restrained Punch 1D4 M.D.; Full Strength Punch or Kick 2D6 M.D.; Power Punch 4D6 M.D. (counts as two attacks)', 1, 'Hand to hand', NULL, NULL, NULL, 'Robotic P.S. 38.'),
  ('ripper-cyborg-shocktrooper', 1, 'Mini-Missile Back Launch Tubes (2; rear)', 'Varies with missile type; standard issue is armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'About a mile (1.6 km)', 'One at a time or volleys of two or four', '18 total, nine per launcher', NULL, 'Primary purpose anti-aircraft and flying monsters. Any mini-missile can be used; fragmentation may be used against ground troops. Two large multi-shot tubes on the back; the top folds open to fire. One minute to reload by hand.'),
  ('ripper-cyborg-shocktrooper', 2, 'Mini-Missile Chest Launch Tubes (2)', 'Varies with missile type; standard issue is armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'About a mile (1.6 km)', 'One at a time or volleys of two or four', '12 total, six per launcher', NULL, 'Primary purpose anti-aircraft and flying monsters. Any mini-missile can be used; fragmentation may be used against ground troops. The chest plates open to reveal them.'),
  ('ripper-cyborg-shocktrooper', 3, 'Tri-Blade Buzz Saw Forearm (1)', '4D6 M.D. from one blade, 1D4x10 M.D. from two (the front and a side blade)', 1, 'Hand to hand; reach of the arm, about 6 feet (1.8 m)', NULL, 'Effectively unlimited; draws on the cyborg''s power', NULL, 'Three saw blades set in a heavily plated V-shaped forearm shield, one at the front and one on each side. The shield blocks hand to hand attacks and missiles. Bonus: +1 to parry and +3 to disarm when using this weapon.'),
  ('ripper-cyborg-shocktrooper', 4, 'Cheek Lasers', '2D6 M.D. per single blast, or 4D6 M.D. per simultaneous dual blast at the same target', 1, '1,600 ft (488 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-personnel and defense. Two light lasers in the cheeks; each rotates 90 degrees in all directions.'),
  ('ripper-cyborg-shocktrooper', 5, 'Chemical Spray', 'Varies with the type of chemical', 0, '20 ft (6 m)', 'Each blast counts as one melee attack', '20', NULL, 'Primary purpose anti-personnel and defense. Sprayed from the mouth; see the Rifts RPG, page 240. May also spray holy water. The line is headed "Damage", not "Mega-Damage".'),
  ('ripper-cyborg-shocktrooper', 6, 'Concealed Laser Rod (1)', '3D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-personnel and defense. Concealed in the left leg.'),
  ('ripper-cyborg-shocktrooper', 7, 'W-42 Concealed Palm Laser', 'Four settings: 2D4x10 S.D.C., 1D4 M.D., 1D6 M.D., or 2D6 M.D. per single blast', 1, '400 feet (122 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose tactical weapon and tool/self-defense. A larger, heavier W-42 built into the base of the left palm and wrist; also a cutting tool.'),
  ('ripper-cyborg-shocktrooper', 8, 'Vibro-Blade Fingers (2)', '2D6 M.D.', 1, 'Hand to hand; about six feet (1.8 m)', NULL, NULL, NULL, 'Curved, silver plated blades on the two large fingers, for slashing and cutting. The punch table (weapon 9) prints Raking Vibro-Claws (left hand) as 3D6 M.D.'),
  ('ripper-cyborg-shocktrooper', 9, 'Robot P.S. and Punch Damage', 'Head Butt 2D6 M.D.; Raking Vibro-Claws (left hand) 3D6 M.D.; Vibro-Claw Clamping/Cut (left hand) 4D6 M.D.; Restrained Punch 1D4 M.D.; Full Strength Punch or Kick 3D6 M.D.; Power Punch or Leap Kick 1D6x10 M.D. (counts as two attacks)', 1, 'Hand to hand', NULL, NULL, NULL, 'Robotic P.S. 44. Also see the buzz saw damage.'),
  ('white-tiger-cyborg-shocktrooper', 1, 'Mini-Missile Chest Launch Tubes (2)', 'Varies with missile type; standard issue is armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'About a mile (1.6 km)', 'One at a time or volleys of two or four', '12 total, six per launcher', NULL, 'Primary purpose anti-aircraft and flying monsters. Any mini-missile can be used; fragmentation may be used against ground troops. The chest plates open to reveal them.'),
  ('white-tiger-cyborg-shocktrooper', 2, 'Chemical Spray', 'Varies with the type of chemical', 0, '20 ft (6 m)', 'Each blast counts as one melee attack', '20', NULL, 'Primary purpose anti-personnel and defense. Sprayed from the mouth; see the Rifts RPG, page 240. The line is headed "Damage", not "Mega-Damage".'),
  ('white-tiger-cyborg-shocktrooper', 3, 'Vibro-Blade Fingers', '1D4 M.D. from a single finger; 3D4 M.D. from a slashing claw strike; or 2D4 M.D. added to the 3D6 M.D. of a full strength punch (stabbing attack, fingers pointing out)', 1, 'Hand to hand; about six feet (1.8 m)', NULL, NULL, NULL, 'A curved, silver plated blade on each finger and thumb, for slashing, cutting and climbing.'),
  ('white-tiger-cyborg-shocktrooper', 4, 'Tri-Laser Forearm Weapon', '2D6 M.D. per single blast, 4D6 M.D. per double blast, or 6D6 M.D. per triple blast', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-armor and anti-monster. A small, low-profile triple-shot laser in the right forearm that passes for armor plating at a glance. It has no line of its own in the M.D.C. by Location table.'),
  ('white-tiger-cyborg-shocktrooper', 5, 'Concealed Hip Plasma Ejector', '4D6 M.D. per blast', 1, '1,600 ft (488 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose assault and defense. In a compartment on the right hip.'),
  ('white-tiger-cyborg-shocktrooper', 6, 'Concealed Hip Laser Rod (1)', '3D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose assault and defense. In a compartment on the left leg.'),
  ('white-tiger-cyborg-shocktrooper', 7, 'Electro-Tentacles (3)', 'Whip or punch/jab: 1D6 M.D. per tentacle, 3D6 M.D. from all three at once; Electro-Blast adds 1D6x10 S.D.C. or 1D6 M.D. per tentacle, or 3D6 M.D. from all three', 1, '10 feet (3 m) beyond the reach of the arm and hand (about 16 feet/4.9 m total)', 'Once per melee round, and counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-personnel and defense. Three retractable, prehensile tentacles in the left forearm; one, two or all three may be used to entangle, hold, carry, climb or whip. They provide the +1 attack per melee round listed under Bonuses. The whip line prints "1D6 per tentacle" without "M.D."; the "once per melee round" rate is the electrical charge. Electro-Blast: once per melee round a charge adds as little as 1D6x10 S.D.C. or 1D6 M.D. per tentacle, or 3D6 M.D. from all three, added to whip damage or inflicted on anyone touching or held. It may stun for 1D4 melee rounds (victim has two attacks/actions per round, no initiative, -8 on all combat maneuvers, skill performance and speed reduced 70%). Stun chance: 01-92% human/humanoid/D-Bee without body armor; 01-65% mortal M.D.C. being with no body armor or human in armor; 01-50% Light Machine, Partial ''Borg or lesser demon; 01-30% Heavy Machine, power armored opponent or greater demon; 01-05% Cyborg Shocktrooper, robot, adult dragon or demon lord. P.S. of tentacles: 15.'),
  ('white-tiger-cyborg-shocktrooper', 8, 'Robot P.S. and Punch Damage', 'Head Butt 2D6 M.D.; Restrained Punch 1D4 M.D.; Full Strength Punch or Kick 3D6 M.D.; Power Punch or Leap Kick 1D6x10 M.D. (counts as two attacks)', 1, 'Hand to hand', NULL, NULL, NULL, 'Robotic P.S. 46.'),
  ('holocaust-cyborg-shocktrooper', 1, 'Mini-Missile Launchers (2)', 'Varies with missile type; standard issue is armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.)', 1, 'About a mile (1.6 km)', 'One at a time or volleys of two or four', '54 total; 27 per launcher', NULL, 'Primary purpose anti-aircraft and flying monsters. Any mini-missile can be used; fragmentation may be used against ground troops. Two box launchers: one at the front right above the tread, one at the back in the middle of the track behind the cyborg''s hip.'),
  ('holocaust-cyborg-shocktrooper', 2, 'Shoulder Plasma Cannon', '6D6 M.D. per blast', 1, '2000 feet (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-cyborg and anti-monster. Behind the right shoulder; swings forward from storage, 45 degree arc up and down and 45 degrees left and right.'),
  ('holocaust-cyborg-shocktrooper', 3, 'Forearm Pulse Laser', '1D6 M.D. per single blast, 2D6 M.D. per double pulse or 4D6 M.D. per quadruple pulse blast', 1, '3000 feet (914 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose long-range attacks and defense. Mounted on the right forearm.'),
  ('holocaust-cyborg-shocktrooper', 4, 'Shoulder Rail Gun', '1D6 M.D. per single blast, 1D6x10 M.D. per 20 round burst', 1, '6,000 feet (1828 m)', 'Each burst counts as one melee attack', '200 bursts; a 4000 round drum is mounted in the rear behind the cyborg', NULL, 'Primary purpose long-range attacks and anti-armor and anti-monster. Behind the left shoulder; can be loaded with silver-plated rounds; swings forward from storage, 45 degree arc and 45 degrees left and right.'),
  ('holocaust-cyborg-shocktrooper', 5, 'Forearm Particle Beam Gun', '1D4x10 M.D. per blast', 1, '1000 feet (305 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose close combat and defense. The two halves of the housing open to reveal the gun. Left forearm per the M.D.C. table.'),
  ('holocaust-cyborg-shocktrooper', 6, 'Robot P.S. and Punch Damage', 'Head Butt 3D6 M.D.; Restrained Punch 1D4 M.D.; Full Strength Punch 3D6 M.D. (2D6 M.D. for the small arms); Power Punch 1D6x10 M.D. (4D6 M.D. for the small arms; counts as two attacks); Ram 5D6 M.D. (counts as two attacks)', 1, 'Hand to hand', NULL, NULL, NULL, 'Robotic P.S. 40. No kick is printed (the body has treads).'),
  ('aftermath-cyborg-shocktrooper', 1, 'Chain Saw Multi-Weapon Arm (1)', 'Chain Saw: 5D6 M.D. Vibro-Blade Arm: 2D4 M.D. Mini-Missiles: damage varies by type.', 1, 'Chain Saw and Vibro-Blade: 12 foot (3.6 m) reach. Mini-Missile: a mile (1.6 km).', 'Saw or Blade: hand to hand combat. Mini-Missiles: one at a time or volleys of two.', 'Mini-Missiles: six total; three per each side of the arm launcher.', NULL, 'Primary purpose assault. Right arm. The curved Vibro-Blade under the saw housing is the hand of a small retractable arm that slides out to swing and stab; the mini-missiles fire from two openings at the base of the saw.'),
  ('aftermath-cyborg-shocktrooper', 2, 'Shoulder Particle Beam Cannon', '1D6x10 M.D. per blast', 1, '2000 feet (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-cyborg and anti-monster. Behind the right shoulder; swings from its storage position on the back to the front. 45 degree arc of fire up and down, and can turn 45 degrees left and right.'),
  ('aftermath-cyborg-shocktrooper', 3, 'Forearm Rail Gun', '1D4 M.D. per single blast, 1D4x10 M.D. per 20 round burst', 1, '4,000 feet (1220 m)', 'Each burst counts as one melee attack', '100 bursts; a 2000 round drum is mounted on the back', NULL, 'Primary purpose long-range attacks and anti-armor & anti-monster. Underside of the left forearm; a light rail gun (the entry''s introduction calls it a heavy rail gun). Can be loaded with silver-plated rounds.'),
  ('aftermath-cyborg-shocktrooper', 4, 'Concealed Vibro-Blade', '2D6 M.D.', 1, 'Hand to hand combat; about 10 feet (3 m) when extended (3 feet/0.9 m longer than the arm)', NULL, NULL, NULL, 'Large, silver plated; housed in the circular compartment above the left hand and extended as needed.'),
  ('aftermath-cyborg-shocktrooper', 5, 'Robot P.S. and Punch Damage', 'Head Butt 2D6 M.D.; Restrained Punch 1D4 M.D.; Full Strength Punch 3D6 M.D.; Power Punch 1D6x10 M.D. (counts as two attacks); Running Ram 5D6 M.D. (counts as two attacks)', 1, 'Hand to hand', NULL, NULL, NULL, 'The chain saw can be used like a club when turned off.'),
  ('avenging-angel-cyborg-shocktrooper', 1, 'Vibro-Scythe Polearm (1)', 'Vibro-Scythe: 4D6 M.D. Ion Blaster: adjustable to 2D6 or 4D6 M.D. blasts.', 1, 'Ion Blaster: 1,200 ft (366 m). Vibro-Blade: melee combat, the reach of the pole-arm, roughly 13 feet (4 m). Or 600 feet (183 m) when thrown like a spear by the cyborg.', 'Each blast counts as one melee attack', '30 blasts before needing recharging, via a special connector cable to the cyborg''s power supply (three minutes for a complete recharge). Or powered by a standard E-Clip (15 shots).', NULL, 'Primary purpose assault and defense. Hand-held, giant-sized and golden, made for the Avenging Angel. Silver plated Vibro-Weapon blade that cuts and stabs; the pole end is a blunt weapon and fires the ion blasts. The ''Borg uses it one- or two-handed; for all others it is a two-handed weapon and a bit large for ordinary humans. The entry prints no strike bonus and no cost for it; the only bonus tied to it is the body''s +1 melee attack when the pole-arm is the only weapon used that round other than claws.'),
  ('avenging-angel-cyborg-shocktrooper', 2, 'Wing Mini-Missiles (8)', 'Varies with missile type; standard issue is armor piercing (1D4x10 M.D.) or plasma (1D6x10). Fragmentation may be used against ground troops.', 1, 'About a mile (1.6 km)', 'One at a time or volleys of two or four', '8 total, four per wing', NULL, 'Primary purpose anti-aircraft and flying monsters. Self-launching; hooked to the shoulder end of each wing. Any mini-missile can be used.'),
  ('avenging-angel-cyborg-shocktrooper', 3, 'Concealed Forearm Lasers (2)', '1D6 M.D. per single blast, 2D6 per simultaneous dual blast at the same target (counts as one melee attack)', 1, '1,600 feet (488 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-personnel and defense. One concealed light laser in each arm.'),
  ('avenging-angel-cyborg-shocktrooper', 4, 'Clawed Hands (2)', '3D4 M.D. per claw strike', 1, 'Hand to hand combat; the reach of the arm, about five feet (1.5 m)', NULL, NULL, NULL, 'Each finger on each hand has a silver plated Vibro-Blade.'),
  ('avenging-angel-cyborg-shocktrooper', 5, 'Vibro-Blade Feet', '+2D6 M.D. to kick damage (in addition to P.S. damage), or 2D6 M.D. from raking or clawing attacks and 1D6 M.D. from a glancing blow/cut (one toe-blade hits)', 1, 'Hand to hand combat; the reach of the leg, about 6 feet (1.8 m)', NULL, NULL, NULL, 'The two front toes and the rear talon are tipped with six inch (0.15 m), silver plated Vibro-Blades; used to rake, cut and stab while diving.'),
  ('avenging-angel-cyborg-shocktrooper', 6, 'Robot P.S. and Punch Damage', 'Claw Strike 3D4 M.D.; Head Butt 2D4 M.D.; Restrained Punch 1D4 M.D.; Full Strength Punch 2D6 M.D.; Power Punch 4D6 M.D.; Kick 2D6 M.D. +2D6 M.D. from the Vibro-Blades; Flying Leap Kick or Power Dive (feet first) 1D6x10', 1, 'Hand to hand', NULL, NULL, NULL, 'Flying Leap Kick or Power Dive also has a 01-75% likelihood of knocking the opponent off his feet and/or stunning him for one melee round (15 seconds): the stunned victim has only two attacks/actions that round, no initiative, -8 on all combat maneuvers, and skill performance and speed reduced by 70%. The stun does not work on giant robots, cyborgs weighing more than two tons, vehicles, adult dragons, demon lords or similar giant or superhuman creatures. The Power Punch line does not print the usual ''counts as two attacks'', and the dive prints ''1D6x10 damage'' without ''M.D.''.'),
  ('assassin-cyborg-shocktrooper', 1, 'One Arm out of Four: Retractable Vibro-Blades', '2D6 M.D.', 1, 'Hand to hand', NULL, NULL, NULL, 'A pair of retractable Vibro-Blades. The same arm has a Wrist Needle and Drug Dispenser (Rifts RPG, page 241) and a fingerjack.'),
  ('assassin-cyborg-shocktrooper', 2, 'One Arm out of Four: Mekanikal Vibro-Blade Multi-Weapon Arm', 'Laser: 2D6 M.D. Large underarm Vibro-Blade/Sword: 3D6 M.D. Vibro-Claw Fingers: 4D4 M.D.', 1, NULL, NULL, NULL, NULL, 'Described in the Cybernetics section of this book; this entry prints only the three damage lines, no range or payload.'),
  ('assassin-cyborg-shocktrooper', 3, 'One Arm out of Four: Forearm Particle Beam Gun', '6D6+6 M.D. Explosive knuckle spikes: 1D4 M.D.', 1, 'Particle beam gun: 1000 ft/305 m. Knuckle spikes: 50 ft/15.2 m.', NULL, NULL, NULL, 'The same arm has a climb cord and grappling hook (Rifts RPG page 240), shooting explosive knuckle spikes, and a finger camera (Rifts RPG, page 239).'),
  ('assassin-cyborg-shocktrooper', 4, 'One Arm out of Four: Tool Hand Laser Cutter Finger', 'Adjustable: 1D6x10 S.D.C., one M.D., 1D4 M.D. or 1D6 M.D.', 1, '6 foot (182 cm) beam', NULL, NULL, NULL, 'Part of the Tool Hand (fingerjack, fingertip screwdrivers, finger pliers, fingertip lights, retractable drill in the middle knuckle). The arm also has a Garrote Wrist Wire (Rifts RPG, page 240) and an optional forearm weapon; about half have one, and it may be substituted with a small secret compartment.'),
  ('assassin-cyborg-shocktrooper', 5, 'Robot P.S. and Punch Damage', 'Claw Strike 4D4 M.D.; Head Butt 1D6 M.D.; Restrained Punch 1D4 M.D.; Full Strength Punch 2D6 M.D.; Power Punch 4D6 M.D. (counts as two melee attacks); Kick 2D6 M.D.', 1, 'Hand to hand', NULL, NULL, NULL, NULL),
  ('mantis-cyborg-shocktrooper', 1, 'Long Vibro-Blades', '3D6+2 M.D. each', 1, 'Hand to hand combat; about 10 feet/3 m (4 feet/1.2 m longer than the arms)', NULL, NULL, NULL, 'A pair of long, curved, serrated blades, one on top of each forearm, used to parry and kill.'),
  ('mantis-cyborg-shocktrooper', 2, 'Forearm Vibro-Blades', '4D4 M.D.', 1, 'Hand to hand combat', NULL, NULL, NULL, 'Four small jagged blades along the outer side of each forearm; used for climbing, parrying and slashing.'),
  ('mantis-cyborg-shocktrooper', 3, 'Forearm Light Laser Battery', '1D6 M.D. per single blast, 2D6 per dual blast, or 6D6 from a full simultaneous laser volley at the same target (counts as one melee attack)', 1, '2,000 feet (610 m)', 'Each blast, whether one, two or six simultaneous laser bolts, counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose assault and defense. Six light lasers in each forearm, firing one, two or six at a time. Both arms cannot be fired at the same time. Plus, one arm has a Garrote Wrist Wire (Rifts RPG, page 240).'),
  ('mantis-cyborg-shocktrooper', 4, 'Robot P.S. and Punch Damage', 'Head Butt 1D6 M.D.; Bite 1D4 M.D.; Restrained Punch 1D4 M.D.; Full Strength Punch 3D6 M.D.; Power Punch or Leap Kick 1D6x10 M.D. (counts as two melee attacks); Kick 4D6 M.D.', 1, 'Hand to hand', NULL, NULL, NULL, NULL),
  ('demonfist-cyborg-shocktrooper', 1, 'Shoulder Plasma Ejector Cannons (2)', '1D4x10 M.D. per single blast or 2D4x10 per simultaneous dual blast (counts as one melee attack)', 1, '2,000 feet (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-armor and anti-monster. Mounted on the back between the shoulders; one or both swing from the storage position to the front. 45 degree arc of fire up and down; they cannot move side to side, but the Demonfist can rotate 360 degrees at the hips. Comparatively short range for such large guns.'),
  ('demonfist-cyborg-shocktrooper', 2, 'Forearm Lasers (2)', '4D6 M.D. per dual blast', 1, '2,000 feet (610 m)', 'Each dual blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-personnel & anti-monster. A double-barrelled laser on each forearm. Both arm weapons cannot be fired simultaneously at the same target. (The M.D.C. table calls these Forearm Guns.)'),
  ('demonfist-cyborg-shocktrooper', 3, 'Triple Vibro-Blade (1)', '3D6 M.D. + Robot P.S. damage', 1, 'Hand to hand combat; about 11 feet (3.3 m)', NULL, NULL, NULL, 'Three silver-plated Vibro-Blades that extend over the right hand from the circular compartment above it.'),
  ('demonfist-cyborg-shocktrooper', 4, 'Concealed Ion Rod (1)', '4D6 M.D. per blast', 1, '1,600 feet (488 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Primary purpose anti-personnel & defense. Concealed in the left leg.'),
  ('demonfist-cyborg-shocktrooper', 5, 'Left Hand Weapons & Features', 'Laser Finger: 1D6 M.D. Silver Palm Needle: 1D6 S.D.C.', 1, 'Laser Finger: 500 feet (152 m). Chemical Spray: 15 foot (4.6 m).', NULL, 'Chemical Spray: 10 doses', NULL, 'Chemical Spray: 10 doses, 15 foot (4.6 m) range; besides the chemicals on page 240 of the Rifts RPG it is often loaded with holy water. Silver Palm Needle: used against the supernatural. Also a Fingerjack.'),
  ('demonfist-cyborg-shocktrooper', 6, 'Right Hand Weapons & Features', 'Laser Finger: 1D6 M.D.', 1, 'Laser Finger: 500 feet (152 m). Chemical Spray: 15 foot (4.6 m).', NULL, 'Chemical Spray: 10 doses', NULL, 'Chemical Spray: 10 doses, 15 foot (4.6 m) range; besides the chemicals on page 240 of the Rifts RPG it is often loaded with holy water. Garrote Wire: for strangling; located in the palm.'),
  ('demonfist-cyborg-shocktrooper', 7, 'Robot P.S. and Punch Damage', 'Head Butt 3D6 M.D.; Restrained Punch 1D6 M.D.; Full Strength Punch or Kick 3D6 M.D.; Power Punch 1D6x10 M.D. (counts as two attacks); Running Ram 6D6 M.D. (counts as two attacks)', 1, 'Hand to hand', NULL, NULL, NULL, NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 17 Warlords of Russia cyborg bodies are in' AS assertion, count(*) AS got, 17 AS want
  FROM vehicles WHERE slug IN ('warlord-light-machine-cyborg', 'warlord-heavy-machine-cyborg', 'sovietski-light-machine-cyborg', 'sovietski-heavy-machine-cyborg', 'thunderhammer-cyborg-shocktrooper', 'thunderstrike-cyborg-shocktrooper', 'thunderstorm-artillery-cyborg', 'tempest-cyborg-shocktrooper', 'butcher-cyborg-shocktrooper', 'ripper-cyborg-shocktrooper', 'white-tiger-cyborg-shocktrooper', 'holocaust-cyborg-shocktrooper', 'aftermath-cyborg-shocktrooper', 'avenging-angel-cyborg-shocktrooper', 'assassin-cyborg-shocktrooper', 'mantis-cyborg-shocktrooper', 'demonfist-cyborg-shocktrooper') AND source_book LIKE 'Rifts World Book 17: Warlords of Russia p.%';
SELECT 'their 174 M.D.C. locations are in' AS assertion, count(*) AS got, 174 AS want
